/**
 * Swift source for the generated files (iOS build spec, section 7.1): string literals escaped,
 * identifiers checked, and the header that says where a file comes from. Output depends only on
 * the input, in the input's order, so generating twice gives the same bytes.
 */

/** The first line of every generated Swift file. */
export function generatedHeader(source: string): string {
  return `// Generated by pnpm mobile:generate from ${source}. Do not edit.`;
}

/**
 * `text` as a Swift string literal. Backslashes (and so `\(`), double quotes and control
 * characters are escaped; everything else, apostrophes, curly quotes and `$` included, is written
 * as it is, since the files are UTF-8.
 */
export function swiftString(text: string): string {
  let out = '"';
  for (const ch of text) {
    const code = ch.codePointAt(0)!;
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || (code >= 0x7f && code < 0xa0) || code === 0x2028 || code === 0x2029)
      out += `\\u{${code.toString(16)}}`;
    else out += ch;
  }
  return `${out}"`;
}

// Swift's keywords that can't name a member without backticks.
const KEYWORDS = new Set([
  'as',
  'case',
  'class',
  'default',
  'do',
  'else',
  'enum',
  'extension',
  'false',
  'for',
  'func',
  'if',
  'import',
  'in',
  'init',
  'is',
  'let',
  'nil',
  'private',
  'protocol',
  'public',
  'return',
  'self',
  'static',
  'struct',
  'super',
  'switch',
  'true',
  'var',
  'where',
  'while',
]);

/**
 * `name` as a Swift member name: a lower camel case ASCII name (the lint's rule), in backticks
 * when it is a keyword. Anything else throws, so a key that can't be one stops the generator.
 */
export function swiftIdentifier(name: string): string {
  if (!/^[a-z][A-Za-z0-9]*$/.test(name)) {
    throw new Error(`Not a lower camel case Swift name: ${JSON.stringify(name)}`);
  }
  return KEYWORDS.has(name) ? `\`${name}\`` : name;
}
